import React from 'react';
import styles from './RequestCard.module.css';

function RequestCard({ req, user, onAccept, onNotify }) {
  return (
    <div className={styles.card}>
      <div className={styles.info}><strong>Book:</strong> {req.book?.title || 'N/A'}</div>
      <div className={styles.info}><strong>Student:</strong> {req.student?.name || 'N/A'}</div>
      <div className={styles.info}><strong>Status:</strong> {req.status}</div>
      {user?.role === 'librarian' && req.status === 'pending' && (
        <button className={styles.button} onClick={() => onAccept(req._id)}>Accept</button>
      )}
      {user?.role === 'librarian' && req.status === 'accepted' && (
        <button className={styles.button} onClick={() => onNotify(req._id)}>Send Reminder</button>
      )}
    </div>
  );
}

export default RequestCard;
